package io.knowledgebrain.collaboration;
import io.knowledgebrain.contracts.collaboration.submission.v1.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;
import org.apache.kafka.clients.consumer.*;import org.apache.kafka.common.serialization.*;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_GROUP_KAFKA_BOOTSTRAP",matches=".+")
class SubmissionKafkaIntegrationTest {
 @Test void immutableAttemptsMatchCdcBytesAndReplayWithoutAcknowledgement()throws Exception{
  var f=new SubmissionStoreIntegrationTest();f.setup();f.open();var v=f.submit(f.f.key(),0,2,"First answer").submission();f.submit(f.f.key(),1,2,"Revised answer");var expected=new HashMap<String,byte[]>();for(var bytes:f.f.jdbc.queryForList("SELECT payload FROM outbox_event WHERE aggregateid=?",byte[].class,v.submissionId())){var e=SubmissionEnvelopeV1.parseFrom(bytes);expected.put(e.getEventId(),bytes);}assertEquals(2,expected.size());
  var options=new Properties();options.put("bootstrap.servers",System.getenv("BRAIN_TEST_GROUP_KAFKA_BOOTSTRAP"));options.put("group.id","group-validation-"+UUID.randomUUID());options.put("enable.auto.commit","false");options.put("auto.offset.reset","earliest");options.put("key.deserializer",StringDeserializer.class.getName());options.put("value.deserializer",ByteArrayDeserializer.class.getName());options.put("security.protocol","SSL");options.put("ssl.endpoint.identification.algorithm","HTTPS");options.put("ssl.truststore.type","PEM");options.put("ssl.keystore.type","PEM");options.put("ssl.truststore.certificates",Files.readString(Path.of("/group-kafka-test/ca.crt")));options.put("ssl.keystore.certificate.chain",Files.readString(Path.of("/group-kafka-test/user.crt")));options.put("ssl.keystore.key",Files.readString(Path.of("/group-kafka-test/user.key")));
  for(int replay=0;replay<2;replay++){var seen=new HashSet<String>();try(var consumer=new KafkaConsumer<String,byte[]>(options)){consumer.subscribe(List.of("collaboration.submission.v1"));long deadline=System.nanoTime()+Duration.ofSeconds(60).toNanos();while(seen.size()<2&&System.nanoTime()<deadline)for(var record:consumer.poll(Duration.ofMillis(300))){var e=SubmissionEnvelopeV1.parseFrom(record.value());if(!expected.containsKey(e.getEventId()))continue;assertArrayEquals(expected.get(e.getEventId()),record.value());assertEquals(v.submissionId().toString(),record.key());assertEquals(f.f.trace,e.getTraceId());assertEquals(f.space.toString(),e.getSpaceId());assertEquals(f.author.toString(),e.getActorId());var p=SubmissionSnapshotV1.parseFrom(e.getPayload());assertEquals(f.assignment.toString(),p.getAssignmentId());assertEquals("AUTHOR_AND_OWNER",p.getAudience());assertEquals(2,p.getAssignmentVersion());for(var entry:Map.of("trace_id",f.f.trace,"schema_group","collaboration","schema_artifact","submission-events","schema_version","1").entrySet())assertEquals(entry.getValue(),new String(record.headers().lastHeader(entry.getKey()).value(),StandardCharsets.UTF_8));seen.add(e.getEventId());}}assertEquals(expected.keySet(),seen);}
  System.out.println("PASS collaboration.submission.v1 two byte-exact private answer snapshots, stable IDs, trace/schema headers and unacknowledged replay");
 }
}
